package web.arena;
import org.junit.*;import web.account.AccountDatabase;import web.arena.repository.ArenaInventoryRepository;import java.io.File;import java.lang.reflect.Field;import java.nio.file.Files;import java.sql.*;import static org.junit.Assert.*;
public class ArenaInventoryRepositoryTest{private File dir;private AccountDatabase db;private ArenaInventoryRepository repo;@Before public void setup()throws Exception{dir=Files.createTempDirectory("arena-items").toFile();db=new AccountDatabase();Field f=AccountDatabase.class.getDeclaredField("dbPath");f.setAccessible(true);f.set(db,new File(dir,"lobby.db").getPath());db.init();try(Connection c=db.getConnection();Statement s=c.createStatement()){s.execute("CREATE TABLE arena_player(user_id INTEGER PRIMARY KEY,coins INTEGER NOT NULL)");s.execute("INSERT INTO arena_player VALUES(1,1000)");}repo=new ArenaInventoryRepository(db);repo.init();repo.seed(1);}@After public void close(){for(File f:dir.listFiles())f.delete();dir.delete();}
@Test public void craftMovesMaterialsAndCoinsAtomically()throws Exception{repo.craft(1,"herb",3,"pill",1,100);assertEquals(9,qty("herb"));assertEquals(1,qty("pill"));assertEquals(900,coins());}
@Test public void insufficientMaterialRollsBackCoinCharge()throws Exception{try{repo.craft(1,"herb",99,"pill",1,100);fail();}catch(IllegalArgumentException expected){}assertEquals(1000,coins());assertEquals(12,qty("herb"));}
private int qty(String id)throws Exception{try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("SELECT quantity FROM arena_item WHERE user_id=1 AND item_id=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}}private int coins()throws Exception{try(Connection c=db.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT coins FROM arena_player WHERE user_id=1")){r.next();return r.getInt(1);}}
}
